 async function startDirector(request:string){
  if(directorSubmitting.current||checkingCompatibility)return;
  if(request.length<3||request.length>2000){setError('El encargo del Director debe tener entre 3 y 2000 caracteres. Tu texto se conserva.');return;}
  if(attachments.length){setError('La delegación automática admite solo texto. Para documentos o cálculos, usa Datos/Tareas y revisa el plan.');return;}
  const pid=project,version=contextVersion.current;
  const previous=directorSubmission.current,submission=previous?.project===pid&&previous.request===request?previous:{project:pid,request,id:crypto.randomUUID()};directorSubmission.current=submission;
  directorSubmitting.current=true;setDirectorStarting(true);setError('');setNotice('');
  try{
   await requireDirectorSupport();
   if(version!==contextVersion.current||context.current.project!==pid)return;
   setDirectorCompatibility(false);
   const response=await fetchApi('/api/director',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:pid,request,confirmed:true,request_id:submission.id})});
   if(response.status===404||response.status===405)throw new ServerCompatibilityError();
   if(response.status===422&&directorSubmission.current===submission)directorSubmission.current=null;
   const result:Run=await readApiResponse(response);
   if(version!==contextVersion.current||context.current.project!==pid)return;
   setRuns(old=>[result,...old.filter(run=>run.id!==result.id)]);setSelectedRun(result.id);setDelegateToTeam(false);directorSubmission.current=null;
   setText(old=>old.trim()===request?'':old);setNotice('ANTO ha preparado el encargo del equipo. Puedes seguir el progreso o cancelarlo aquí.');
   refresh(pid).catch(e=>{if(version===contextVersion.current)setError('El encargo está guardado, pero no se pudo actualizar su progreso. '+e.message);});
  }catch(e){if(version===contextVersion.current){if(e instanceof ServerCompatibilityError)setDirectorCompatibility(true);setError((e as Error).message);}}
  finally{directorSubmitting.current=false;setDirectorStarting(false);}
 }
