  if(attachments.reduce((sum,a)=>sum+(a.size||0),0)+(f.size||0)>12*1024*1024){setError('Los adjuntos de un mensaje pueden sumar hasta 12 MB. El archivo permanece en tu biblioteca.');return false;}
